{
  "narrative_summary": "Rebuild In House produced the best outcome in 58% of runs of this model, and Extend Vendor Contract produced the best outcome in 42%. The link from Engineering Capacity to Total Cost of Ownership is not yet evidence backed.",
  "story_headlines": {
    "opt_rebuild": "Rebuild In House depends on engineering capacity holding up as modelled over time.",
    "opt_extend": "Extend Vendor Contract would need the vendor price path to stay favourable to lead here."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 61% of variations, based on current estimates given the low overall confidence.",
    "primary_risk": "The link from Engineering Capacity to Total Cost of Ownership is fragile and could flip which option this model points to.",
    "stability_factors": [],
    "fragility_factors": [
      "The link from Engineering Capacity to Total Cost of Ownership could shift the comparison if capacity assumptions change."
    ]
  },
  "readiness_rationale": "Two gaps still hold this back: engineering capacity is asserted rather than evidenced, and confidence in that factor and in the vendor price path remains low.",
  "evidence_enhancements": {
    "fac_eng_capacity": {
      "specific_action": "Run a capacity audit against current engineering commitments to test the assumption behind this comparison.",
      "rationale": "This factor is asserted rather than evidenced, and the comparison is sensitive to it.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the likely capacity shortfall before looking at the audit results."
    },
    "fac_vendor_price": {
      "specific_action": "Request a multi-year price commitment or cap from the vendor to firm up this input.",
      "rationale": "The vendor price path feeds Total Cost of Ownership and is only moderately evidenced.",
      "evidence_type": "market_research",
      "decision_hygiene": "Write down the expected price range before opening vendor negotiations."
    }
  },
