    {
      "type": "unsupported_link",
      "source": "structural",
      "description": "Engineering capacity is asserted rather than evidenced, yet it shapes the comparison. Is that assumption tested enough to lean on?",
      "affected_elements": [
        "edge_capacity_tco"
      ],
      "suggested_action": "Validate engineering capacity assumptions with a concrete audit before committing.",
      "linked_critique_code": "unsupported_link"
