  ],
  "key_assumptions": [
    "The link from Engineering Capacity to Total Cost of Ownership assumes current team capacity estimates are accurate.",
    "The link from Vendor Price Path to Total Cost of Ownership assumes pricing trends continue as currently expected.",
    "The framing assumes billing platform direction is decided primarily on cost rather than other operational factors."
  ],
  "decision_quality_prompts": [
    {
      "question": "What is the base rate for efforts like Rebuild In House delivering on their engineering capacity assumptions?",
      "principle": "Outside View (Kahneman)",
      "applies_because": "Overall confidence in this comparison is low, so grounding the estimate in comparable past efforts helps test it."
    },
    {
      "question": "Who will argue that Engineering Capacity matters less than Total Cost of Ownership modelling suggests?",
      "principle": "Structured dissent",
      "applies_because": "A critique flagged that engineering capacity is asserted rather than evidenced, so surfacing dissent tests that assumption directly."
    }
  ]
